function notes(S, x, y, z, n = 3) { for (let i = 0; i < n; i++) { const b = mesh(new T3.BoxGeometry(.16, .004, .08), mat(0x8a9a6a)); b.position.set(x + i * .03, y + i * .005, z + i * .02); b.rotation.set(.05, i * .4, .08); S.scene.add(b); } }
function radio(S, o = {}) { const g = new T3.Group(); const b = mesh(new T3.BoxGeometry(.5, .3, .16), mat(o.color ?? 0x5a3a2a)); g.add(b);
  const gr = mesh(new T3.BoxGeometry(.22, .2, .01), mat(0x2a2a2a)); gr.position.set(-.1, 0, .08); g.add(gr); const k = mesh(new T3.CylinderGeometry(.03, .03, .03, 12), mat(0xcfc6b0)); k.rotation.x = Math.PI / 2; k.position.set(.15, .05, .085); g.add(k);
  const ant = beam(V(.2, .15, 0), V(.32, .5, 0), .006, mat(0x9a9a9a, { metalness: .8 })); g.add(ant); if (o.open) { b.material = mat(o.color ?? 0x5a3a2a); b.scale.y = .4; b.position.y = -.09; const pcb = mesh(new T3.BoxGeometry(.4, .02, .12), mat(0x2f6b3f)); pcb.position.y = .0; g.add(pcb); for (let i = 0; i < 8; i++) { const c = mesh(new T3.BoxGeometry(.03, .03, .03), mat(i % 2 ? 0x111111 : 0xb8a070)); c.position.set(-.15 + i * .04, .025, (i % 3 - 1) * .03); g.add(c); } }
  return g; }
function lit(S, x, y, z, color, I, dist = 10) { const l = new T3.PointLight(color, I, dist, 1.5); l.position.set(x, y, z); S.scene.add(l); return l; }
function sunGlow(S, pos, color = 0xffc27a, size = 30, o = .85) { const g = glow(color, size, o); g.position.set(...pos); S.scene.add(g); return g; }
function stars(S, seed = 2) { const r = rng(seed), sp = new Float32Array(900); for (let i = 0; i < 300; i++) { const a = r() * 6.3, e = .1 + r() * 1.3, R = 400; sp[i * 3] = Math.cos(a) * Math.cos(e) * R; sp[i * 3 + 1] = Math.sin(e) * R; sp[i * 3 + 2] = Math.sin(a) * Math.cos(e) * R; }
  const g = new T3.BufferGeometry(); g.setAttribute('position', new T3.BufferAttribute(sp, 3)); S.scene.add(new T3.Points(g, new T3.PointsMaterial({ color: 0xffffff, size: 1.6, sizeAttenuation: false, fog: false }))); }
