function clouds(S, n, y, z, color = 0xfff3e0, speed = 2) { const cs = []; for (let i = 0; i < n; i++) { const c = cloud(color, 30 + i * 4); c.position.set(-70 + i * 24, y + (i % 3) * 6, z); S.scene.add(c); cs.push(c); } S.ticks.push(T => cs.forEach((c, i) => c.position.x = -70 + i * 24 + T * speed)); return cs; }
function school(S, z = -14) { const g = new T3.Group(); const sb = mesh(new T3.BoxGeometry(18, 3.4, 5), mat(0xa0583c)); sb.position.y = 1.7; g.add(sb);
  for (let i = 0; i < 6; i++) { const w = mesh(new T3.BoxGeometry(1.2, 1, .1), mat(0x24201c)); w.position.set(-7 + i * 2.8, 2, 2.52); g.add(w); }
  const dr = mesh(new T3.BoxGeometry(1.4, 2.2, .1), mat(0x3a2418)); dr.position.set(0, 1.1, 2.52); g.add(dr);
  const rf = mesh(new T3.BoxGeometry(19, .1, 6), mat(0x8d8f93, { metalness: .5, roughness: .5 })); rf.position.y = 3.6; rf.rotation.x = .08; g.add(rf); g.position.z = z; S.scene.add(g); return g; }
function windDiagram(S, o = {}) { const blue = new T3.MeshBasicMaterial({ color: o.color ?? 0x6fe0ff, wireframe: true, transparent: true, opacity: .85 }); const wm = windmill({ h: 3 }); wm.g.traverse(m => { if (m.isMesh) m.material = blue; }); S.scene.add(wm.g); return wm; }
